def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v, default=(0, 0)):
        try:
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return int(v[0]), int(v[1])
        except:
            pass
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def safe_list(x):
        return x if isinstance(x, list) else []

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))
    me = (sx, sy)
    opp = (ox, oy)

    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(me, opp)
        # evader: move away; if tied or blocked later, bias toward center
        moves = [
            step_away(me, opp),
            [0, clamp_step((gh // 2) - sy)],
            [clamp_step((gw // 2) - sx), 0],
            [0, 0],
        ]
        best = moves[0]
        best_score = manhattan((sx + best[0], sy + best[1]), opp)
        for mv in moves[1:]:
            sc = manhattan((sx + mv[0], sy + mv[1]), opp)
            if sc > best_score:
                best = mv
                best_score = sc
        return best

    if env == "territory_control":
        targets = []
        for key in ("unclaimed_cells", "opponent_territory", "neutral_cells", "frontier_cells"):
            vals = safe_list(observation.get(key))
            if vals:
                targets = vals
                break
        if not targets:
            # Move toward center or opponent territory if nothing explicit exists
            cx = gw // 2
            cy = gh // 2
            return [clamp_step(cx - sx), clamp_step(cy - sy)]
        best = None
        best_dist = None
        for item in targets:
            t = pos(item, None)
            if t is None:
                continue
            d = manhattan(me, t)
            if best is None or d < best_dist:
                best = t
                best_dist = d
        if best is None:
            return [0, 0]
        return step_toward(me, best)

    # resource_collection and fallback
    resources = []
    for key in ("resources", "resource_positions", "items", "food"):
        vals = safe_list(observation.get(key))
        if vals:
            resources = vals
            break

    if resources:
        best = None
        best_dist = None
        for item in resources:
            t = pos(item, None)
            if t is None:
                continue
            d = manhattan(me, t)
            if best is None or d < best_dist:
                best = t
                best_dist = d
        if best is not None:
            return step_toward(me, best)

    # Denial / exploration fallback: drift toward opponent or center depending on context
    if env == "resource_collection":
        return step_toward(me, opp)

    cx = gw // 2
    cy = gh // 2
    return [clamp_step(cx - sx), clamp_step(cy - sy)]

